#!/usr/bin/env sage
"""Valid low-order contraction and Borel obstruction scan for q=121 C1.

Only ordinary invariant differential contractions of orders r < p are
used.  The pullback image is tested after restriction to the split Borel:
the torus-fixed normalization is inherited from the q=121 support module,
and the two additive generators 1,a generate U(F_121).  Since
[PSL_2(121):B]=122 is nonzero in characteristic 11, a nonzero restricted
class certifies a nonzero global class.
"""


# This file was *autogenerated* from the file ../notes/2026-07-29-c665-q121-ordinary-borel.sage
from sage.all_cmdline import *   # import sage library

_sage_const_2 = Integer(2); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0)
import argparse
import importlib.machinery
import importlib.util
import json
from math import comb
from pathlib import Path


HERE = Path(__file__).resolve().parent
DETECTOR_PATH = HERE / "2026-07-28-c665-q121-contraction-detector.sage"
CERTIFICATE = HERE / "2026-07-29-c665-q121-ordinary-borel.json"


def load_detector():
    loader = importlib.machinery.SourceFileLoader(
        "c665_q121_detector_support", str(DETECTOR_PATH)
    )
    spec = importlib.util.spec_from_loader(loader.name, loader)
    if spec is None:
        raise RuntimeError(f"cannot load {DETECTOR_PATH}")
    module = importlib.util.module_from_spec(spec)
    loader.exec_module(module)
    return module


detector = load_detector()
pullback = detector.pullback
base = detector.base
FIELD = detector.FIELD
A = detector.A
R = detector.R
X, Y, Z = detector.X, detector.Y, detector.Z
HALF = FIELD(_sage_const_2 ) ** -_sage_const_1 


def partial(polynomial, dx, dy, dz):
    answer = polynomial
    if dx:
        answer = answer.derivative(X, dx)
    if dy:
        answer = answer.derivative(Y, dy)
    if dz:
        answer = answer.derivative(Z, dz)
    return answer


def ordinary_contraction(left, right, order):
    """Power of d_X d_Z' - (1/2)d_Y d_Y' + d_Z d_X'."""
    answer = R.zero()
    for pair_xz in range(order + _sage_const_1 ):
        for pair_yy in range(order - pair_xz + _sage_const_1 ):
            pair_zx = order - pair_xz - pair_yy
            coefficient = (
                comb(order, pair_xz)
                * comb(order - pair_xz, pair_yy)
                * (-HALF) ** pair_yy
            )
            answer += coefficient * partial(
                left, pair_xz, pair_yy, pair_zx
            ) * partial(right, pair_zx, pair_yy, pair_xz)
    return answer


def pullback_inputs():
    group_elements = (
        (_sage_const_1 , _sage_const_1 , _sage_const_0 , _sage_const_1 ),
        (_sage_const_1 , A, _sage_const_0 , _sage_const_1 ),
        (_sage_const_0 , -_sage_const_1 , _sage_const_1 , _sage_const_0 ),
    )
    generator_data = [pullback.action_data(g) for g in group_elements]
    primitive = FIELD.multiplicative_generator()
    torus_element = (primitive, _sage_const_0 , _sage_const_0 , primitive**-_sage_const_1 )
    torus_data = pullback.action_data(torus_element)
    _, _, adjusted_cocycles = pullback.split_torus_fixed_lift(
        generator_data, torus_data
    )
    _, embedding_columns, simple_actions = pullback.embedding_polynomials()
    embedded_images = []
    for simple_action in simple_actions:
        columns = []
        for simple_column in range(base.SIMPLE_DEGREE + _sage_const_1 ):
            columns.append(
                sum(
                    (
                        simple_action[source_simple, simple_column]
                        * embedding_columns[source_simple]
                        for source_simple in range(
                            base.SIMPLE_DEGREE + _sage_const_1 
                        )
                        if simple_action[source_simple, simple_column]
                    ),
                    R.zero(),
                )
            )
        embedded_images.append(columns)
    return adjusted_cocycles, embedded_images, simple_actions


def test_order(order, adjusted_cocycles, embedded_images, simple_actions):
    defects = []
    for cocycle, image_columns in zip(
        adjusted_cocycles[:_sage_const_2 ], embedded_images[:_sage_const_2 ]
    ):
        defects.append(
            [
                ordinary_contraction(cocycle, image, order)
                for image in image_columns
            ]
        )
    nonzero_defect_columns = sum(
        bool(defect)
        for generator_defects in defects
        for defect in generator_defects
    )
    target_degree = _sage_const_2  * (base.DEGREE - order)
    if nonzero_defect_columns:
        system = detector.contraction_system(
            defects, simple_actions[:_sage_const_2 ], target_degree
        )
    else:
        system = {
            "target_degree": target_degree,
            "target_dimension": (
                (target_degree + _sage_const_1 ) * (target_degree + _sage_const_2 ) // _sage_const_2 
            ),
            "torus_block_variables": _sage_const_0 ,
            "equations": _sage_const_0 ,
            "coefficient_rank": _sage_const_0 ,
            "augmented_rank": _sage_const_0 ,
            "solvable": True,
        }
    system["contraction_order"] = order
    system["nonzero_defect_columns"] = nonzero_defect_columns
    return system


def calculate(orders):
    adjusted_cocycles, embedded_images, simple_actions = pullback_inputs()
    channels = []
    for order in orders:
        record = test_order(
            order, adjusted_cocycles, embedded_images, simple_actions
        )
        channels.append(record)
        if not record["solvable"]:
            break
    detecting = next(
        (record for record in channels if not record["solvable"]), None
    )
    return {
        "schema": _sage_const_1 ,
        "q": base.Q,
        "p": base.P,
        "field_modulus": str(FIELD.modulus()),
        "subgroup": "split Borel",
        "subgroup_index_mod_p": (base.Q + _sage_const_1 ) % base.P,
        "ordinary_contraction_orders": list(orders),
        "channels": channels,
        "detecting_contraction_order": (
            None if detecting is None else detecting["contraction_order"]
        ),
        "conclusion": (
            "a valid ordinary contraction detects the restricted pullback"
            if detecting is not None
            else "the checked valid ordinary contractions are Borel-blind"
        ),
    }


def parse_orders(specification):
    if "-" in specification and "," not in specification:
        start, stop = map(int, specification.split("-", _sage_const_1 ))
        return tuple(range(start, stop + _sage_const_1 ))
    return tuple(int(value) for value in specification.split(","))


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--orders", default="1-10")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = parser.parse_args()
    orders = parse_orders(args.orders)
    if not orders or any(order < _sage_const_1  or order >= base.P for order in orders):
        raise ValueError("orders must lie between 1 and p-1")
    result = calculate(orders)
    encoded = json.dumps(result, default=int, indent=_sage_const_2 , sort_keys=True) + "\n"
    if args.write:
        CERTIFICATE.write_text(encoded)
        print(f"wrote {CERTIFICATE.name}")
    elif args.check:
        assert CERTIFICATE.read_text() == encoded
        print(f"checked {CERTIFICATE.name}")
    else:
        print(encoded, end="")


if __name__ == "__main__":
    main()

